/** Shared language cases: original regression suite and automatic engine parity discovery. */
export const cases = [
 ['nested rethrow restores lexical exception','try{try{throw new Exception("outer");}catch(Exception e){try{throw new Exception("inner");}catch(Exception f){Console.WriteLine(f.Message);}throw;}}catch(Exception g){Console.WriteLine(g.Message);}','inner\nouter\n'],
 ['auto property', 'var c = new C(); c.X += 4; Console.WriteLine(c.X); class C { public int X { get; set; } = 3; }', '7\n'],
 ['expression getter', 'var c=new C(){X=7}; Console.WriteLine(c.Double); class C { public int X { get; set; } public int Double => X*2; }','14\n'],
 ['explicit accessors','var c=new C(); c.X=5; Console.WriteLine(c.X); class C { int x; public int X { get {return x;} set {x=value*2;} } }','10\n'],
 ['expression accessors','var c=new C(); c.X=5; Console.WriteLine(c.X); class C { int x; public int X { get => x; set => x=value+1; } }','6\n'],
 ['getter only constructor','Console.WriteLine(new C(12).Id); class C { public int Id { get; } public C(int id) {this.Id=id;} }','12\n'],
 ['static auto initialization','Console.WriteLine(C.Y); C.X++; Console.WriteLine(C.Y); class C { public static int X {get;set;}=7; public static int Y => X+1; }','8\n9\n'],
 ['assignment results','var c=new C(); Console.WriteLine(c.X=3); Console.WriteLine(c.X++); Console.WriteLine(++c.X); Console.WriteLine(c.X+=2); class C { public int X{get;set;} }','3\n3\n5\n7\n'],
 ['property receiver evaluated once','class C { public int X {get;set;} } class P {static int calls;static C c=new C();static C Next(){calls++;return c;}static void Main(){Next().X+=4;Console.WriteLine(calls);Console.WriteLine(c.X);}}','1\n4\n'],
 ['coalescing property','var c=new C(); Console.WriteLine(c.X??="a"); Console.WriteLine(c.X??="b"); class C {public string X{get;set;}}','a\na\n'],
 ['private setter inside owner','var c=new C(); c.Set(8); Console.WriteLine(c.X); class C {public int X {get;private set;} public void Set(int x){X=x;}}','8\n'],
 ['nameof property','Console.WriteLine(nameof(C.X));class C {public int X{get;set;}}','X\n'],
 ['normal finally','try {Console.WriteLine(1);} finally {Console.WriteLine(2);}','1\n2\n'],
 ['return preserves value','int F(){int x=1;try{return x;}finally{x=2;Console.WriteLine(x);}}Console.WriteLine(F());','2\n1\n'],
 ['return reference remains rooted','C F(){try{return new C();}finally{GC.Collect();}}Console.WriteLine(F().X);class C{public int X=7;}','7\n'],
 ['exception finally then catch','try{try{throw new Exception("x");}finally{Console.WriteLine(1);}}catch(Exception e){Console.WriteLine(e.Message);}','1\nx\n'],
 ['try catch finally','try{throw new Exception("x");}catch(Exception e){Console.WriteLine(e.Message);}finally{Console.WriteLine(2);}','x\n2\n'],
 ['nested finally','int F(){try{return 3;}finally{try{Console.WriteLine(4);}finally{Console.WriteLine(5);}}}Console.WriteLine(F());','4\n5\n3\n'],
 ['catch inside finally preserves return','int F(){try{return 3;}finally{try{throw new Exception("inner");}catch(Exception e){Console.WriteLine(e.Message);}}}Console.WriteLine(F());','inner\n3\n'],
 ['throw from finally overrides return','int F(){try{return 3;}finally{throw new Exception("last");}}try{Console.WriteLine(F());}catch(Exception e){Console.WriteLine(e.Message);}','last\n'],
 ['throw from finally overrides exception','try{try{throw new Exception("first");}finally{throw new Exception("last");}}catch(Exception e){Console.WriteLine(e.Message);}','last\n'],
 ['break finally','while(true){try{break;}finally{Console.WriteLine(1);}}Console.WriteLine(2);','1\n2\n'],
 ['continue finally','for(int i=0;i<3;i++){try{continue;}finally{Console.WriteLine(i);}}','0\n1\n2\n'],
 ['loop internal finally','try{Console.WriteLine(0);}finally{for(int i=0;i<4;i++){if(i==1)continue;if(i==3)break;Console.WriteLine(i);}}','0\n0\n2\n'],
 ['empty protected clauses','try{}finally{}try{}catch(Exception e){}finally{}Console.WriteLine(1);','1\n'],
 ['catch return runs final','int F(){try{throw new Exception("x");}catch(Exception e){return 9;}finally{Console.WriteLine(1);}}Console.WriteLine(F());','1\n9\n'],
 ['property setter finally','var c=new C();c.X=7;Console.WriteLine(c.X);class C {int x;public int X{get=>x;set{try{x=value;}finally{Console.WriteLine("set");}}}}','set\n7\n'],
];
export const diagnosticCases=[
 ['getter-only write','var c=new C();c.X=1;class C {public int X{get;}}','CS0200'],
 ['private setter','var c=new C();c.X=1;class C{public int X{get;private set;}}','CS0272'],
 ['write-only read','Console.WriteLine(new C().X);class C{public int X{set{}}}','CS0154'],
 ['duplicate getter','Console.WriteLine(1);class C{public int X{get;get;}}','CS1007'],
 ['auto write-only','Console.WriteLine(1);class C{public int X{set;}}','CS8051'],
 ['return exits finally','int F(){try{return 1;}finally{return 2;}}Console.WriteLine(F());','CS0157'],
 ['break exits finally','while(true){try{}finally{break;}}','CS0157'],
 ['continue exits finally','while(true){try{}finally{continue;}}','CS0157'],
 ['init remains explicit limitation','Console.WriteLine(1);class C{public int X{get;init;}}','CS1014'],
];
export const languageFixtures=[
 ...cases.map(([name,source,output])=>({id:'release05/'+name,source,expected:{output}})),
 ...diagnosticCases.map(([name,source,code])=>({id:'release05/diagnostic/'+name,source,compileFailure:true,diagnosticCodes:[code]}))
];
